<?php declare(strict_types=1); require_once dirname(__DIR__,2).'/lib/tool-page.php'; $tool=['title'=>'Free Lorem Ipsum Generator','description'=>'Generate placeholder Lorem Ipsum text for designs and prototypes.','url'=>'https://smarttoolz.in/tools/lorem-generator/']; smarttoolz_tool_page_start($tool); ?><main class="tool-page"><section class="tool-intro"><h1>Lorem Ipsum Generator</h1><p>Generate placeholder paragraphs instantly.</p></section><section class="tool-workspace"><div class="tool-panel"><label>Paragraphs<input id="n" type="number" min="1" max="20" value="3"></label><button id="go" class="tool-btn">Generate</button><textarea id="o" rows="14" readonly></textarea></div></section></main><script>const s='Lorem ipsum dolor sit amet, consectetur adipiscing elit. Sed do eiusmod tempor incididunt ut labore et dolore magna aliqua.';go.onclick=()=>o.value=Array.from({length:Math.min(20,Math.max(1,+n.value||1))},()=>s).join('\n\n');go.click()</script><?php smarttoolz_tool_page_end(); ?>